export default class Onglet {
  constructor() {
    this.count = 1;
    this.favicon = document.querySelector('link[rel="icon"]');
    this.init();
    this.originalTitle = document.title;
    this.awayTitle = 'Reviens.. on a pas fini';
  }

  init() {
    var intervalID = window.setInterval(this.myCallback.bind(this), 2000);
    document.addEventListener('visibilitychange', this.titleChange.bind(this));
  }

  myCallback() {
    this.count++;
    if (this.count == 5) this.count = 1;
    this.favicon.href = `assets/icons/icone${this.count}.svg`;
  }

  titleChange() {
    if (document.hidden) {
      document.title = this.awayTitle;
    } else {
      document.title = this.originalTitle;
    }
  }
}
